<script lang="ts">
 import {onMount} from 'svelte'; import {get,post} from '$lib/api';
 let rows:any[]=$state([]),foods:any[]=$state([]),nutrients:any[]=$state([]),show=$state(false),selected:any=$state(null),error=$state(''),message=$state('');
 let form:any=$state({experiment_code:'',food_uid:'',sample_code:'',preparation_method:'',analytical_method:'',laboratory:'',experiment_date:'',status:'draft',notes:''});
 let result:any=$state({nutrient_code:'',value:'',unit:'',replicate_number:'',lod:'',loq:'',uncertainty:'',qc_status:'unreviewed',notes:''});
 async function load(){try{[rows,foods,nutrients]=await Promise.all([get('/api/experiments?limit=200'),get('/api/foods?limit=500'),get('/api/nutrients')])}catch(e:any){error=e.message}}
 async function create(){try{const e=await post('/api/experiments',form);message=`Created experiment ${e.experiment_code}`;show=false;form={experiment_code:'',food_uid:'',sample_code:'',preparation_method:'',analytical_method:'',laboratory:'',experiment_date:'',status:'draft',notes:''};await load()}catch(e:any){error=e.message}}
 async function openExperiment(uid:string){try{selected=await get(`/api/experiments/${uid}`)}catch(e:any){error=e.message}}
 async function addResult(){try{await post(`/api/experiments/${selected.experiment_uid}/results`,result);message='Experimental result recorded with QC metadata.';result={nutrient_code:'',value:'',unit:'',replicate_number:'',lod:'',loq:'',uncertainty:'',qc_status:'unreviewed',notes:''};await openExperiment(selected.experiment_uid)}catch(e:any){error=e.message}}
 onMount(load);
</script>
<div class="page-head"><div><span class="kicker">Analytical evidence</span><h1>Experiment manager</h1><p>Record food samples, analytical methods, replicates, detection limits and QC status. Experimental results remain separate from the curated food-composition value until explicitly reviewed.</p></div><button class="btn" onclick={()=>show=true}>＋ New experiment</button></div>
{#if error}<div class="error" style="margin-bottom:12px">{error}</div>{/if}{#if message}<div class="success" style="margin-bottom:12px">{message}</div>{/if}
<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Experiment</th><th>Food</th><th>Sample</th><th>Method</th><th>Laboratory</th><th>Status</th><th>Date</th></tr></thead><tbody>{#each rows as e}<tr onclick={()=>openExperiment(e.experiment_uid)} style="cursor:pointer"><td class="mono"><b>{e.experiment_code}</b></td><td>{e.food_name||'—'}</td><td>{e.sample_code||'—'}</td><td>{e.analytical_method||'—'}</td><td>{e.laboratory||'—'}</td><td><span class="status">{e.status}</span></td><td>{e.experiment_date||'—'}</td></tr>{/each}</tbody></table>{#if !rows.length}<div class="empty">No new research experiments yet. Historical composition remains preserved in the migrated food records.</div>{/if}</div></div>
{#if show}<div class="drawer-backdrop"><section class="drawer"><div class="drawer-head"><div><span class="kicker">Experimental provenance</span><h2>New experiment</h2></div><button class="close" onclick={()=>show=false}>×</button></div><div class="form-grid"><div class="field"><label>Experiment code <input bind:value={form.experiment_code} placeholder="Auto if blank"/></label></div><div class="field"><label>Food <select bind:value={form.food_uid}><option value="">Select food…</option>{#each foods as f}<option value={f.food_uid}>{f.legacy_food_id} · {f.food_name}</option>{/each}</select></label></div><div class="field"><label>Sample code <input bind:value={form.sample_code}/></label></div><div class="field"><label>Preparation <input bind:value={form.preparation_method}/></label></div><div class="field"><label>Analytical method <input bind:value={form.analytical_method}/></label></div><div class="field"><label>Laboratory <input bind:value={form.laboratory}/></label></div><div class="field"><label>Date <input type="date" bind:value={form.experiment_date}/></label></div><div class="field"><label>Status <select bind:value={form.status}><option>draft</option><option>in_progress</option><option>complete</option><option>curated</option></select></label></div><div class="field span-2"><label>Notes <textarea bind:value={form.notes}></textarea></label></div></div><div class="panel-actions"><button class="btn secondary" onclick={()=>show=false}>Cancel</button><button class="btn" onclick={create}>Create experiment</button></div></section></div>{/if}
{#if selected}<div class="drawer-backdrop"><section class="drawer"><div class="drawer-head"><div><span class="kicker">{selected.status} · {selected.food_name||'unlinked food'}</span><h2>{selected.experiment_code}</h2><p class="card-sub">Add one analytical result/replicate at a time.</p></div><button class="close" onclick={()=>selected=null}>×</button></div>
<div class="form-grid"><div class="field span-2"><label>Analyte / nutrient <select bind:value={result.nutrient_code}><option value="">Select…</option>{#each nutrients as n}<option value={n.nutrient_code}>{n.component_group} · {n.display_name} ({n.unit})</option>{/each}</select></label></div><div class="field"><label>Value <input type="number" step="any" bind:value={result.value}/></label></div><div class="field"><label>Unit override <input bind:value={result.unit} placeholder="uses definition if blank"/></label></div><div class="field"><label>Replicate <input type="number" bind:value={result.replicate_number}/></label></div><div class="field"><label>QC status <select bind:value={result.qc_status}><option>unreviewed</option><option>accepted</option><option>flagged</option><option>rejected</option></select></label></div><div class="field"><label>LOD <input type="number" step="any" bind:value={result.lod}/></label></div><div class="field"><label>LOQ <input type="number" step="any" bind:value={result.loq}/></label></div><div class="field"><label>Uncertainty <input type="number" step="any" bind:value={result.uncertainty}/></label></div><div class="field span-2"><label>Result notes <textarea bind:value={result.notes}></textarea></label></div></div><div class="notice warn" style="margin-top:14px">Recording an experimental result does not overwrite the food's curated composition value. This protects measurement provenance.</div><div class="panel-actions"><button class="btn" onclick={addResult}>Add result</button></div>
{#if selected.results?.length}<h2 style="font-family:inherit;font-size:13px;margin-top:22px">Recorded results</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Analyte</th><th>Value</th><th>Replicate</th><th>QC</th></tr></thead><tbody>{#each selected.results as r}<tr><td>{r.display_name}</td><td>{r.value ?? '—'} {r.unit}</td><td>{r.replicate_number ?? '—'}</td><td><span class="status">{r.qc_status}</span></td></tr>{/each}</tbody></table></div>{/if}</section></div>{/if}
